-- Function: public.fn_get_recipients_for_child
-- Backup generated on 2026-10-25 20:33:41

CREATE OR REPLACE FUNCTION public.fn_get_recipients_for_child(p_tenant_id uuid, p_child_id uuid)  RETURNS TABLE(person_id uuid, user_id uuid, full_name text, relationship character varying, email character varying, mobile_phone character varying, can_receive_information boolean, receives_daily_updates boolean, has_portal_access boolean, photo_consent_granted boolean)  LANGUAGE sql  STABLE AS $function$     SELECT DISTINCT         p.id AS person_id,         p.user_id,         TRIM(CONCAT(p.first_name, ' ', p.last_name)) AS full_name,         COALESCE(cg.relationship, fr.relationship, p.relationship, 'Guardian')::VARCHAR AS relationship,         COALESCE(p.email, u.email)::VARCHAR AS email,         p.mobile_phone,         COALESCE(cg.can_receive_information, TRUE) AS can_receive_information,         COALESCE(p.receives_daily_updates, TRUE) AS receives_daily_updates,         COALESCE(p.has_portal_access, FALSE) AS has_portal_access,         TRUE AS photo_consent_granted     FROM persons p     LEFT JOIN child_guardians cg ON cg.person_id = p.id AND cg.child_id = p_child_id     LEFT JOIN family_relationships fr ON fr.user_id = p.user_id AND fr.child_id = p_child_id     LEFT JOIN users u ON p.user_id = u.id     WHERE p.tenant_id = p_tenant_id       AND (cg.child_id = p_child_id OR fr.child_id = p_child_id)       AND (fr.id IS NULL OR (fr.status = 'Verified' AND fr.revoked_at IS NULL)); $function$ ;
